content:
:root {
  --primary-color: #ff6b6b;
  --primary-hover: #fa5252;
  --secondary-color: #4dabf7;
  --secondary-color-hover: #339af0;
  --reset-color: #868e96;
  --reset-color-hover: #495057;
  --bg-color: #f8f9fa;
  --card-bg: #ffffff;
  --text-color: #343a40;
  --shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #ff6b6b;
    --primary-hover: #ff8787;
    --secondary-color: #4dabf7;
    --secondary-color-hover: #74c0fc;
    --reset-color: #adb5bd;
    --reset-color-hover: #ced4da;
    --bg-color: #1a1a1a;
    --card-bg: #242424;
    --text-color: #f8f9fa;
    --shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  padding: 20px;
}

.timer-card {
  background-color: var(--card-bg);
  border-radius: 24px;
  box-shadow: var(--shadow);
  padding: 40px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.timer-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 24px;
  color: var(--text-color);
}

.timer-display {
  font-size: 4.5rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--text-color);
  margin-bottom: 32px;
  letter-spacing: -2px;
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
}

.btn {
  flex: 1;
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
  color: #ffffff;
}

.btn:active {
  transform: scale(0.96);
}

.btn:focus-visible {
  outline: 3px solid var(--secondary-color);
  outline-offset: 2px;
}

.btn-start {
  background-color: var(--primary-color);
}

.btn-start:hover {
  background-color: var(--primary-hover);
}

.btn-pause {
  background-color: var(--secondary-color);
}

.btn-pause:hover {
  background-color: var(--secondary-color-hover);
}

.btn-reset {
  background-color: var(--reset-color);
}

.btn-reset:hover {
  background-color: var(--reset-color-hover);
}

@media (max-width: 480px) {
  .timer-card {
    padding: 24px;
  }

  .timer-display {
    font-size: 3.5rem;
  }
}

import { useState, useEffect, useCallback } from 'react'

export default function App() {
  const TOTAL_TIME = 25 * 60 // 25 minutes in seconds
  const [timeLeft, setTimeLeft] = useState<number>(TOTAL_TIME)
  const [isRunning, setIsRunning] = useState<boolean>(false)

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60)
    const secs = seconds % 60
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`
  }

  const playAlarmSound = () => {
    try {
      const AudioContext = window.AudioContext || (window as unknown as { webkitAudioContext: typeof window.AudioContext }).webkitAudioContext
      if (!AudioContext) return
      const audioCtx = new AudioContext()
      const osc = audioCtx.createOscillator()
      const gain = audioCtx.createGain()
      osc.type = 'sine'
      osc.frequency.setValueAtTime(587.33, audioCtx.currentTime) // D5
      gain.gain.setValueAtTime(0.1, audioCtx.currentTime)
      osc.connect(gain)
      gain.connect(audioCtx.destination)
      osc.start()
      osc.stop(audioCtx.currentTime + 0.6)
    } catch {
      // Audio context might be blocked by browser policy
    }
  }

  const handleStart = useCallback(() => {
    setIsRunning(true)
  }, [])

  const handlePause = useCallback(() => {
    setIsRunning(false)
  }, [])

  const handleReset = useCallback(() => {
    setIsRunning(false)
    setTimeLeft(TOTAL_TIME)
  }, [TOTAL_TIME])

  useEffect(() => {
    const formatted = formatTime(timeLeft)
    if (isRunning) {
      document.title = `(${formatted}) ポモドーロタイマー`
    } else {
      document.title = 'ポモドーロタイマー'
    }
  }, [timeLeft, isRunning])

  useEffect(() => {
    let interval: number | undefined
    if (isRunning && timeLeft > 0) {
      interval = window.setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            setIsRunning(false)
            playAlarmSound()
            return 0
          }
          return prev - 1
        })
      }, 1000)
    }
    return () => {
      if (interval) clearInterval(interval)
    }
  }, [isRunning, timeLeft])

  return (
    <div className="app-container">
      <div className="timer-card">
        <h1 className="timer-title">ポモドーロタイマー</h1>
        <div className="timer-display">{formatTime(timeLeft)}</div>
        <div className="controls">
          {!isRunning ? (
            <button className="btn btn-start" onClick={handleStart}>
              開始
            </button>
          ) : (
            <button className="btn btn-pause" onClick={handlePause}>
              一時停止
            </button>
          )}
          <button className="btn btn-reset" onClick={handleReset}>
            リセット
          </button>
        </div>
      </div>
    </div>
  )
}
